1333	\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
1334		\label{lem:pasting-measurement}
1335		\lean{MIPStarRE.QPBT.pastedMeasurement_isMeasurement}
1336		\leanok
1337		\uses{def:povm-conventions}
1338		This formalization-only auxiliary is not a named statement of the paper; it
1339		isolates the assertion, left implicit in~\eqref{eq:pasting-2a}, that the
1340		pasted family is a POVM. If $\{(G_1)^x_{g_1}\}_{g_1}$ is a measurement and
1341		$\{(G_2)^x_{g_2}\}_{g_2}$ is a projective measurement, then every operator
1342		$J^x_{g_1,\,g_2}$ is positive and
1343		$\sum_{g_1,\,g_2} J^x_{g_1,\,g_2} = \Id$.
1344	\end{lemma}
1345	\begin{proof}
1346		\leanok \uses{lem:distance-measurement-effect-hermitian}
1347		Positivity holds because $J^x_{g_1,\,g_2}$ is the conjugation of the
1348		positive operator $(G_1)^x_{g_1}$ by the self-adjoint operator
1349		$(G_2)^x_{g_2}$. Summing over $g_1$ first leaves
1350		$\sum_{g_2} (G_2)^x_{g_2} (G_2)^x_{g_2}$, which equals
1351		$\sum_{g_2} (G_2)^x_{g_2} = \Id$ by idempotence and completeness.
1352	\end{proof}
