1356		\lean{MIPStarRE.QPBT.Measurement.leftPlacement, MIPStarRE.QPBT.Measurement.rightPlacement, MIPStarRE.QPBT.Measurement.leftPlacement_effect, MIPStarRE.QPBT.Measurement.rightPlacement_effect}
1357		\leanok
